def _top_help():
    lines = [
        "usage: tallybook [--db FILE] [--today DATE] COMMAND [WORD] [ARGUMENTS]",
        "",
        "Double-entry bookkeeping from the terminal.",
        "",
        "options:",
        "  --db FILE     the book file (default: $TALLYBOOK_DB, else tallybook.db)",
        "  --today DATE  what \"today\" is (default: the real date)",
        "  --version     print the version and stop",
        "  -h, --help    print this help and stop",
        "",
        "commands:",
    ]
    names = [w for w in TOP_ORDER if w in core.ROOT.children]
    names += [w for w in core.ROOT.children if w not in names]
    width = max(len(n) for n in names)
    for name in names:
        node = core.ROOT.children[name]
        if node.cmd is not None:
            text = node.cmd.summary
        else:
            text = " | ".join(node.children)
        lines.append(("  %s  %s" % (name.ljust(width), text)).rstrip())
    lines += ["", "Run 'tallybook COMMAND --help' for the usage of a command."]
    return "\n".join(lines) + "\n"


