    lines = ["usage: tallybook %s WORD [ARGUMENTS]" % " ".join(words), "", "words:"]
    width = max(len(w) for w in node.children)
    for word, child in node.children.items():
        if child.cmd is not None:
            text = child.cmd.summary
        else:
            text = " | ".join(child.children)
        lines.append(("  %s  %s" % (word.ljust(width), text)).rstrip())
    return "\n".join(lines) + "\n"


def _cmd_help(cmd):
    lines = ["usage: tallybook %s" % cmd.usage, "", cmd.summary]
    return "\n".join(lines) + "\n"


